const body = $input.item.json.body || $input.item.json;
const op = body.op || 'get';
const cacheKey = (body.key || '').replace(/[^a-zA-Z0-9._-]/g,'');
const value = body.value || null;
const ttl = parseInt(body.ttl || '300');
const prj = process.env.HOME + '/Library/Mobile Documents/com~apple~CloudDocs/Kit-Piloto-Automatico-V30-DISTRIB';
const db = `${prj}/IMPAR_OS/database/impar.db`;
const { execSync } = require('child_process');
const now = new Date().toISOString();
if (op === 'get' && cacheKey) {
  try {
    const row = execSync(`sqlite3 "${db}" "SELECT content FROM cache_entries WHERE key='${cacheKey}' AND (expires_at IS NULL OR expires_at > '${now}');"`, {timeout:5000}).toString().trim();
    if (row) { execSync(`sqlite3 "${db}" "UPDATE cache_entries SET last_used='${now}', use_count=use_count+1 WHERE key='${cacheKey}';"`, {timeout:3000}); return [{ json: { hit: true, key: cacheKey, value: row, ai_used: false } }]; }
  } catch(e) {}
  return [{ json: { hit: false, key: cacheKey, ai_used: false } }];
}
if (op === 'set' && cacheKey && value !== null) {
  const expires = new Date(Date.now() + ttl*1000).toISOString();
  const safeVal = String(value).replace(/'/g,"''").substring(0,4000);
  try { execSync(`sqlite3 "${db}" "INSERT OR REPLACE INTO cache_entries (key,content,created_at,expires_at,last_used,use_count) VALUES ('${cacheKey}','${safeVal}','${now}','${expires}','${now}',0);"`, {timeout:5000}); } catch(e) { return [{ json: { error: e.message, ai_used: false } }]; }
  return [{ json: { ok: true, key: cacheKey, ttl, ai_used: false } }];
}
if (op === 'del' && cacheKey) {
  try { execSync(`sqlite3 "${db}" "DELETE FROM cache_entries WHERE key='${cacheKey}';"`, {timeout:3000}); } catch(e) {}
  return [{ json: { ok: true, key: cacheKey, ai_used: false } }];
}
return [{ json: { error: 'invalid_op', ai_used: false } }];
